\draw (1,-0.1) -- (1,0.1);\node[below=1pt, font=\scriptsize, fill=white, inner sep=1pt] at (1,-0.1) {$1$};
\draw (2,-0.1) -- (2,0.1);\node[below=1pt, font=\scriptsize, fill=white, inner sep=1pt] at (2,-0.1) {$2$};
